	/**  arXiv id from `eprint` when the entry says it is an arXiv eprint. */
	arxivId?: string | null,
	/**  Link from `url`. */
	url?: string | null,
	/**  Citation key as written in the file. */
	citationKey?: string,
	/**  1-based line of the entry's `@`. */
	line?: number,
	/**  Plain-text abstract. */
