/**  A milestone was added on the plan. */
"milestoneAdded" | 
/**  A milestone moved to a new status. */
"milestoneStatus" | 
/**  A tracked paper gained citing papers. */
"citationAlerts" | 
/**  A daily logbook entry was added. */
"dailyLogs" | 
/**  A weekly logbook entry was added. */
"weeklyLogs";

